from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Discover(EmssimCommand):
    def __init__(self, method="discover", timeout=240, rpc_connection_name='localRPC'):
        super(Discover, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Discover, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "NE reports allConfigurationPlanFile ready for upload"):
                self._ret['upload_file_info'] = data["transfer_info"]
                self._ret['upload_file_info']['ftype'] = data['ftype']
            elif (data["msg"] == "File stored at following path"):
                self._ret['upload_file_info']['path'] = data['path']
            elif (data["msg"] == "Using PDDB default values from file"):
                self._ret["PDDB_default_file"] = data['file']
        elif ("status" in data):
            self._ret["status"] = data["status"]
